"""End-to-end smoke test for the pure-C Win32 UI.

Runs trafficmon_ui.exe against a temporary database, generates loopback traffic with
known byte counts, and checks that the UI process exits cleanly after flushing:

  * application_hourly holds exactly the generated bytes for python.exe
  * the latest collection_session row is mode=etw, closed=1
  * schema is v3
  * --no-etw persists no application bytes and mode=connections

Requires an idle desktop session and administrator rights for the ETW half.
"""
import os
import pathlib
import sqlite3
import subprocess
import sys
import tempfile
from contextlib import closing

ROOT = pathlib.Path(__file__).resolve().parents[1]
EXE = pathlib.Path(os.environ.get("TRAFFICMON_UI_EXE", ROOT / "build" / "trafficmon_ui.exe")).resolve()
GEN = ROOT / "tests" / "gen_known_traffic.py"


def require_no_running_instance():
    result = subprocess.run(["tasklist", "/FI", "IMAGENAME eq trafficmon_ui.exe"],
                            capture_output=True, text=True, errors="replace", timeout=15)
    if "trafficmon_ui.exe" in result.stdout.lower():
        raise SystemExit("close the running TrafficMon UI before running this test")


def run_ui(args, timeout):
    result = subprocess.run([str(EXE), *args], capture_output=True, text=True,
                            encoding="utf-8", errors="replace", timeout=timeout)
    if result.returncode != 0:
        raise AssertionError(f"UI exited {result.returncode}\n{result.stdout}\n{result.stderr}")


def query(db, sql):
    with closing(sqlite3.connect(db)) as connection:
        return connection.execute(sql).fetchall()


def main():
    if not EXE.exists():
        raise SystemExit(f"missing {EXE}; run build_ui.sh first")
    require_no_running_instance()

    with tempfile.TemporaryDirectory(prefix="trafficmon-ui-") as directory:
        db = pathlib.Path(directory) / "ui.sqlite3"

        ui = subprocess.Popen([str(EXE), "--db", str(db), "--exit-after", "10"],
                              stdout=subprocess.PIPE, stderr=subprocess.PIPE,
                              text=True, encoding="utf-8", errors="replace")
        try:
            generator = subprocess.run([sys.executable, str(GEN)], capture_output=True,
                                       text=True, timeout=25)
            if generator.returncode != 0:
                raise AssertionError(generator.stdout + generator.stderr)
            stdout, stderr = ui.communicate(timeout=30)
        finally:
            if ui.poll() is None:
                ui.kill()
                ui.communicate()
        if ui.returncode != 0:
            raise AssertionError(f"UI exited {ui.returncode}\n{stdout}\n{stderr}")

        schema = query(db, "pragma user_version")[0][0]
        assert schema == 3, schema
        rows = query(db, "select identity,sum(up),sum(down) from application_hourly "
                         "group by identity")
        python_rows = [r for r in rows if r[0].lower().endswith("python.exe")]
        unknown_rows = [r for r in rows if r[0].startswith("unknown:") and
                        r[0].endswith(f":{generator.pid}")]
        captured_up = sum(r[1] for r in python_rows + unknown_rows)
        captured_down = sum(r[2] for r in python_rows + unknown_rows)
        session = query(db, "select mode,closed from collection_session "
                            "order by id desc limit 1")
        assert session == [("etw", 1)], session
        if captured_up != 1020 or captured_down != 1020:
            raise AssertionError(
                f"application bytes {captured_up}/{captured_down} != 1020/1020; rows={rows}\n"
                "ETW is unavailable (run the test elevated); fallback passed but live capture "
                "was NOT verified")
        assert query(db, "select count(*) from application_hourly "
                         "where up_lan > up or down_lan > down")[0][0] == 0
        print(f"live: app rows={rows} session={session}")

        no_db = pathlib.Path(directory) / "noetw.sqlite3"
        run_ui(["--db", str(no_db), "--no-etw", "--exit-after", "3"], timeout=20)
        session = query(no_db, "select mode,closed from collection_session "
                               "order by id desc limit 1")
        assert session == [("connections", 1)], session
        assert query(no_db, "select count(*) from application_hourly")[0][0] == 0
        print(f"no-etw: session={session}")

    print("PASS: UI startup, ETW attribution, flush-on-exit, schema v3, no-etw fallback")


if __name__ == "__main__":
    main()